  44→export const loader = async ({ request }: LoaderFunctionArgs) => {
  45→  const { session } = await authenticate.admin(request);
  46→  const shop = session.shop;
  47→
  48→  const [entries, subscription] = await Promise.all([
  49→    db.waitlistEntry.findMany({
  50→      where: { shop },
  51→      orderBy: { createdAt: "desc" },
  52→    }),
  53→    getShopSubscription(shop),
  54→  ]);
  55→
  56→  const stats = {
  57→    total: entries.length,
  58→    waiting: entries.filter((e) => e.status === "waiting").length,
  59→    accepted: entries.filter((e) => e.status === "accepted").length,
  60→    rejected: entries.filter((e) => e.status === "rejected").length,
  61→    notified: entries.filter((e) => e.status === "notified").length,
  62→    converted: entries.filter((e) => e.status === "converted").length,
  63→    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
  64→  };
  65→
  66→  return { entries, stats, subscription };
  67→};
  68→
  69→export const action = async ({ request }: ActionFunctionArgs) => {
  70→  const { session } = await authenticate.admin(request);
  71→  const shop = session.shop;
  72→  const formData = await request.formData();
  73→  const intent = formData.get("intent");
  74→
  75→  if (intent === "add") {
  76→    const email = String(formData.get("email") || "").trim().toLowerCase();
  77→    const zipCode = String(formData.get("zipCode") || "")
  78→      .trim()
  79→      .toUpperCase();
  80→    const note = String(formData.get("note") || "").trim() || null;
  81→
  82→    if (!email || !zipCode) return { error: "Email and zip code are required." };
  83→
  84→    const subscription = await getShopSubscription(shop);
  85→    const limits = PLAN_LIMITS[subscription.planTier];
  86→
  87→    if (limits.maxWaitlist === 0) {
  88→      return { error: "Your current plan does not include waitlist access. Upgrade to Starter or higher." };
  89→    }
  90→
  91→    if (isFinite(limits.maxWaitlist)) {
  92→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
  93→      if (currentCount >= limits.maxWaitlist) {
  94→        return { error: `You have reached the ${limits.maxWaitlist}-entry waitlist limit on your ${limits.label} plan. Upgrade to Pro for unlimited entries.` };
  95→      }
  96→    }
  97→
  98→    try {
  99→      await db.waitlistEntry.create({
 100→        data: { shop, email, zipCode, note },
 101→      });
 102→      return { success: true, action: "added" };
 103→    } catch {
 104→      return { error: "This email is already on the waitlist for this zip code." };
 105→    }
 106→  }
 107→
 108→  if (intent === "delete") {
 109→    const id = String(formData.get("id"));
 110→    await db.waitlistEntry.delete({ where: { id } });
 111→    return { success: true, action: "deleted" };
 112→  }
 113→
 114→  if (intent === "update-status") {
 115→    const id = String(formData.get("id"));
 116→    const status = String(formData.get("status"));
 117→    await db.waitlistEntry.update({ where: { id }, data: { status } });
 118→    return { success: true, action: "updated" };
 119→  }
 120→
 121→  if (intent === "bulk-notify") {
 122→    const zipCode = String(formData.get("zipCode") || "")
 123→      .trim()
 124→      .toUpperCase();
 125→    if (!zipCode) return { error: "Zip code is required." };
 126→
 127→    const bulkNotifySub = await getShopSubscription(shop);
 128→    if (isFinite(PLAN_LIMITS[bulkNotifySub.planTier].maxWaitlist)) {
 129→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 130→    }
 131→
 132→    const updated = await db.waitlistEntry.updateMany({
 133→      where: { shop, zipCode, status: "waiting" },
 134→      data: { status: "notified" },
 135→    });
 136→
 137→    return {
 138→      success: true,
 139→      action: "bulk-notify",
 140→      count: updated.count,
 141→      zipCode,
 142→    };
 143→  }
 144→
 145→  if (intent === "notify-zip") {
 146→    const zipCode = String(formData.get("zipCode") || "").trim().toUpperCase();
 147→    if (!zipCode) return { error: "No ZIP code specified." };
 148→
 149→    const notifyZipSub = await getShopSubscription(shop);
 150→    if (isFinite(PLAN_LIMITS[notifyZipSub.planTier].maxWaitlist)) {
 151→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 152→    }
 153→
 154→    const entries = await db.waitlistEntry.findMany({
 155→      where: { shop, zipCode, status: "waiting" },
 156→      select: { id: true, email: true },
 157→    });
 158→
 159→    if (entries.length === 0) {
 160→      return { action: "notify-zip", zipCode, emails: [] as string[], count: 0 };
 161→    }
 162→
 163→    await db.waitlistEntry.updateMany({
 164→      where: { shop, zipCode, status: "waiting" },
 165→      data: { status: "notified" },
 166→    });
 167→
 168→    const emails = entries.map((e) => e.email);
 169→    return { action: "notify-zip", zipCode, emails, count: emails.length };
 170→  }
 171→
 172→  if (intent === "delete-all-notified") {
 173→    const deleted = await db.waitlistEntry.deleteMany({
 174→      where: { shop, status: "notified" },
 175→    });
 176→    return { success: true, action: "deleted-notified", count: deleted.count };
 177→  }
 178→
 179→  if (intent === "accept") {
 180→    const id = String(formData.get("id"));
 181→    const entry = await db.waitlistEntry.findUnique({ where: { id } });
 182→    if (!entry || entry.shop !== shop) {
 183→      return { error: "Entry not found." };
 184→    }
 185→
 186→    // Add the ZIP code to the allowed list
 187→    await db.zipCode.upsert({
 188→      where: { shop_zipCode: { shop, zipCode: entry.zipCode } },
 189→      create: {
 190→        shop,
 191→        zipCode: entry.zipCode,
 192→        type: "allowed",
 193→        isActive: true,
 194→        label: `Requested by ${entry.name || entry.email}`,
 195→      },
 196→      update: {
 197→        type: "allowed",
 198→        isActive: true,
 199→      },
 200→    });
 201→
 202→    // Mark the waitlist entry as accepted
 203→    await db.waitlistEntry.update({
 204→      where: { id },
 205→      data: { status: "accepted" },
 206→    });
 207→
 208→    return { success: true, action: "accepted", zipCode: entry.zipCode };
 209→  }
 210→
 211→  if (intent === "reject") {
 212→    const id = String(formData.get("id"));
 213→    await db.waitlistEntry.update({
 214→      where: { id },
 215→      data: { status: "rejected" },
 216→    });
 217→    return { success: true, action: "rejected" };
 218→  }
 219→
 220→  return null;
 221→};
