125→export const loader = async ({ request }: LoaderFunctionArgs) => {
126→  const { session } = await authenticate.admin(request);
127→  const shop = session.shop;
128→  const subscription = await getShopSubscription(shop);
129→  return { subscription };
130→};
131→
132→// ─── Action ───────────────────────────────────────────────────────────────────
133→
134→export const action = async ({ request }: ActionFunctionArgs): Promise<
135→  | { error: string }
136→  | { success: boolean; message: string }
137→  | null
138→> => {
139→  const { session, billing } = await authenticate.admin(request);
140→  const shop = session.shop;
141→  const formData = await request.formData();
142→  const intent = String(formData.get("intent"));
143→
144→  if (intent === "subscribe") {
145→    const plan = String(formData.get("plan"));
146→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
147→    try {
148→      /* eslint-disable @typescript-eslint/no-explicit-any */
149→      // billing.request() throws a redirect Response to Shopify's
150→      // billing confirmation page — we must let it propagate.
151→      await billing.request({
152→        plan: plan as any,
153→        isTest: process.env.NODE_ENV !== "production",
154→        returnUrl,
155→      });
156→      /* eslint-enable @typescript-eslint/no-explicit-any */
157→      return null;
158→    } catch (error) {
159→      // Re-throw Response redirects so React Router / App Bridge handles them
160→      if (error instanceof Response) throw error;
161→      // BillingError has errorData with Shopify userErrors
162→      const errorData = (error as { errorData?: Array<{ field?: string; message?: string }> }).errorData;
163→      const details = errorData?.map((e) => e.message).join(", ");
164→      const message = details || (error instanceof Error ? error.message : String(error));
165→
166→      // Provide a helpful message for common billing errors
167→      if (message.includes("Custom apps cannot use the Billing API")) {
168→        return {
169→          error: "Billing is not available for custom apps. Please change your app distribution to 'Public' in the Shopify Partner Dashboard.",
170→        };
171→      }
172→      return {
173→        error: `Failed to initiate subscription: ${message}`,
174→      };
175→    }
176→  }
177→
178→  // Set plan directly in database (for custom apps where Billing API is unavailable)
179→  if (intent === "test-set-plan") {
180→    const tier = String(formData.get("tier")) as import("../plans").PlanTier;
181→    const validTiers = ["free", "starter", "pro", "ultimate"];
182→    if (!validTiers.includes(tier)) {
183→      return { error: `Invalid plan tier: ${tier}` };
184→    }
185→    const planId = tier === "free" ? "free" : `${tier.charAt(0).toUpperCase() + tier.slice(1)} Monthly`;
186→    await db.subscription.upsert({
187→      where: { shop },
188→      create: { shop, planId, billingInterval: "monthly", status: "active" },
189→      update: { planId, billingInterval: "monthly", status: "active", shopifySubscriptionId: null },
190→    });
191→    return { success: true, message: `Plan set to ${tier.charAt(0).toUpperCase() + tier.slice(1)}.` };
192→  }
193→
194→  if (intent === "cancel") {
195→    try {
196→      const sub = await getShopSubscription(shop);
197→      if (sub.shopifySubscriptionId) {
198→        await billing.cancel({
199→          subscriptionId: sub.shopifySubscriptionId,
200→          isTest: process.env.NODE_ENV !== "production",
201→          prorate: true,
202→        });
203→      }
204→      await cancelShopSubscription(shop);
205→      return {
206→        success: true,
207→        message: "Subscription cancelled. You are now on the Free plan.",
208→      };
209→    } catch {
210→      return { error: "Failed to cancel subscription. Please try again." };
211→    }
212→  }
213→
214→  return null;
215→};
