234→type PlanCardProps = {
235→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
236→  isAnnual: boolean;
237→  currentTier: string;
238→  onSubscribe: (planName: string) => void;
239→  onRequestCancel: () => void;
