242→
243→function PlanCard({
244→  plan,
245→  isAnnual,
246→  currentTier,
247→  onSubscribe,
248→  onRequestCancel,
249→  loadingPlan,
250→}: PlanCardProps) {
251→  const isCurrent = currentTier === plan.id;
252→  const isBestValue = "bestValue" in plan && plan.bestValue;
253→  const isCurrentPaid = currentTier !== "free";
254→  const isDowngradeToFree = plan.id === "free" && isCurrentPaid;
255→
256→  const TIER_ORDER: Record<string, number> = {
257→    free: 0,
258→    starter: 1,
259→    pro: 2,
260→    ultimate: 3,
261→  };
262→  const isUpgrade =
263→    !isCurrent &&
264→    plan.id !== "free" &&
265→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
266→
267→  const shopifyPlan = isAnnual
268→    ? plan.shopifyPlanAnnual
269→    : plan.shopifyPlanMonthly;
270→
271→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
272→
273→  let buttonContent = "Start 7-day free trial";
274→  if (isCurrent) {
275→    buttonContent = "Current plan";
276→  } else if (isDowngradeToFree) {
277→    buttonContent = "Downgrade to Free";
278→  } else if (isUpgrade) {
279→    buttonContent = `Upgrade to ${plan.name}`;
280→  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
281→    buttonContent = `Switch to ${plan.name}`;
282→  }
283→
284→  const handleClick = () => {
285→    if (isCurrent) return;
286→    if (isDowngradeToFree) {
287→      onRequestCancel();
288→    } else if (shopifyPlan) {
289→      onSubscribe(shopifyPlan);
290→    }
291→  };
292→
293→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
294→
295→  return (
296→    <Card>
297→      <BlockStack gap="400">
298→
299→        {/* Plan name + badges */}
300→        <BlockStack gap="100">
301→          <InlineStack align="space-between" blockAlign="center">
302→            <Text as="h3" variant="headingMd" fontWeight="bold">
303→              {plan.name}
304→            </Text>
305→            <InlineStack gap="150">
306→              {isBestValue && (
307→                <Badge tone="info" icon={StarIcon}>
308→                  Most popular
309→                </Badge>
310→              )}
311→              {isCurrent && <Badge tone="success">Active</Badge>}
312→            </InlineStack>
313→          </InlineStack>
314→          <Text as="p" variant="bodySm" tone="subdued">
315→            {plan.description}
316→          </Text>
317→        </BlockStack>
318→
319→        <Divider />
320→
321→        {/* Price */}
322→        <BlockStack gap="100">
323→          {plan.monthlyPrice === 0 ? (
324→            <>
325→              <Text as="p" variant="headingXl" fontWeight="bold">
326→                Free
327→              </Text>
328→              <Text as="p" variant="bodySm" tone="subdued">
329→                forever
330→              </Text>
331→            </>
332→          ) : (
333→            <>
334→              <InlineStack gap="100" blockAlign="baseline">
335→                <Text as="p" variant="headingXl" fontWeight="bold">
336→                  ${displayPrice}
337→                </Text>
338→                <Text as="p" variant="bodySm" tone="subdued">
339→                  / month
340→                </Text>
341→              </InlineStack>
342→              <Text as="p" variant="bodySm" tone="subdued">
343→                {isAnnual
344→                  ? `billed $${plan.annualPrice} / year`
345→                  : `or $${plan.annualMonthlyPrice}/mo billed annually`}
346→              </Text>
347→            </>
348→          )}
349→        </BlockStack>
350→
351→        {/* CTA button */}
352→        <Button
353→          variant={isCurrent ? "secondary" : "primary"}
354→          tone={isDowngradeToFree ? "critical" : undefined}
355→          onClick={handleClick}
356→          disabled={isCurrent}
357→          loading={isThisLoading}
358→          fullWidth
359→        >
360→          {buttonContent}
361→        </Button>
362→
363→        <Divider />
364→
365→        {/* Features list */}
366→        <BlockStack gap="300">
367→          {plan.features.map((f) => (
368→            <PlanFeature key={f} feature={f} />
369→          ))}
370→        </BlockStack>
371→
372→      </BlockStack>
373→    </Card>
374→  );
375→}
