105→   105→    allowed: zipCodes.filter((z) => z.type === "allowed").length,
106→   106→    blocked: zipCodes.filter((z) => z.type === "blocked").length,
107→   107→    active: zipCodes.filter((z) => z.isActive).length,
108→   108→  };
109→   109→
110→   110→  return { zipCodes, stats, subscription };
111→   111→};
